using System.ComponentModel;
using System.Text;
using System.Text.RegularExpressions;

namespace ResearchAgent.Tools;

public sealed partial class WebSearchTool
{
    private readonly HttpClient _httpClient;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
        _httpClient.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
    }

    [Description("Searches the web for a given query and returns a list of result snippets. " +
                 "Use this tool to find information about any topic.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query to look up on the web")] string query,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            var html = await _httpClient.GetStringAsync(url, cancellationToken);

            var results = ParseSearchResults(html);

            if (results.Count == 0)
            {
                return $"No results found for '{query}'.";
            }

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: \"{query}\"");
            sb.AppendLine();

            for (var i = 0; i < Math.Min(results.Count, 5); i++)
            {
                var (title, snippet) = results[i];
                sb.AppendLine($"{i + 1}. **{title}**");
                sb.AppendLine($"   {snippet}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed: {ex.Message}. Try a different query or rephrase.";
        }
    }

    private static List<(string Title, string Snippet)> ParseSearchResults(string html)
    {
        var results = new List<(string, string)>();

        var titleMatches = ResultTitleRegex().Matches(html);
        var snippetMatches = SnippetRegex().Matches(html);

        var count = Math.Min(titleMatches.Count, snippetMatches.Count);
        for (var i = 0; i < count; i++)
        {
            var title = StripHtml(titleMatches[i].Groups[1].Value).Trim();
            var snippet = StripHtml(snippetMatches[i].Groups[1].Value).Trim();

            if (!string.IsNullOrWhiteSpace(title) && !string.IsNullOrWhiteSpace(snippet))
            {
                results.Add((title, snippet));
            }
        }

        return results;
    }

    private static string StripHtml(string input)
    {
        var text = HtmlTagRegex().Replace(input, "");
        text = text.Replace("&amp;", "&")
                   .Replace("&lt;", "<")
                   .Replace("&gt;", ">")
                   .Replace("&quot;", "\"")
                   .Replace("&#39;", "'")
                   .Replace("&nbsp;", " ");
        return WhitespaceRegex().Replace(text, " ").Trim();
    }

    [GeneratedRegex(@"<a[^>]*class=""result__a""[^>]*>(.*?)</a>", RegexOptions.Singleline)]
    private static partial Regex ResultTitleRegex();

    [GeneratedRegex(@"<a[^>]*class=""result__snippet""[^>]*>(.*?)</a>", RegexOptions.Singleline)]
    private static partial Regex SnippetRegex();

    [GeneratedRegex(@"<[^>]+>")]
    private static partial Regex HtmlTagRegex();

    [GeneratedRegex(@"\s+")]
    private static partial Regex WhitespaceRegex();
}

using System.ComponentModel;
using System.Text;

namespace ResearchAgent.Tools;

public sealed class NoteTool
{
    private readonly List<(string Topic, string Content)> _notes = [];

    [Description("Saves a research note with a topic label and content. " +
                 "Use this to record important findings during research.")]
    public string SaveNote(
        [Description("A short topic label for the note (e.g., 'Key definition', 'Historical context')")] string topic,
        [Description("The content of the note — facts, quotes, or insights to remember")] string content)
    {
        _notes.Add((topic, content));
        return $"Note saved under '{topic}' ({_notes.Count} total notes).";
    }

    [Description("Retrieves all saved research notes collected so far.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===");
        sb.AppendLine();

        for (var i = 0; i < _notes.Count; i++)
        {
            var (topic, content) = _notes[i];
            sb.AppendLine($"[{i + 1}] {topic}");
            sb.AppendLine($"    {content}");
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

